SELECT p.id AS position_id, m.id AS wallet_position_id, m.entry_signal_id, m.symbol, m.quantity, m.average_entry_price_usdt, m.total_cost_usdt, m.stop_loss_usdt, m.take_profit_usdt, m.highest_price_usdt, m.profit_lock_active, m.profit_lock_price_usdt, m.profit_lock_progress_percent, m.profit_lock_activated_at, m.profit_lock_state, m.profit_lock_rebase_started_at, m.entry_stage, m.allocated_position_percent, m.entry_quality_score, m.entry_confidence, m.entry_total_score, m.entry_decision, m.near_tp_state, m.near_tp_harvest_used, m.status, m.opened_at, m.updated_at FROM paper_position p JOIN wallet_managed_position m ON m.entry_signal_id = p.signal_id WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id